export function isLang(value) {
    return typeof value === "string" && LANGS.includes(value);
}
/** Picks the phone's language if Avun supports it, otherwise English. */
export function detectLang(navigatorLanguage) {
    const code = (navigatorLanguage ?? "en").slice(0, 2).toLowerCase();
    return isLang(code) ? code : "en";
}
